RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM operational_bindings WHERE calc_operational_bindings_stale_binding_step_key(operational_binding_id) = (SELECT NULLIF(step_id, '') FROM steps WHERE step_id = p_step_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_steps_authoritative_stale_count
-- Field: Steps.AuthoritativeStaleCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_steps_authoritative_stale_count(p_step_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM operational_bindings WHERE calc_operational_bindings_authoritative_stale_step_key(operational_binding_id) = (SELECT NULLIF(step_id, '') FROM steps WHERE step_id = p_step_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_steps_available_exception_count
-- Field: Steps.AvailableExceptionCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_steps_available_exception_count(p_step_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM exceptions WHERE calc_exceptions_active_exception_step_key(exception_id) = (SELECT NULLIF(step_id, '') FROM steps WHERE step_id = p_step_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_steps_declared_verification_count
-- Field: Steps.DeclaredVerificationCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_steps_declared_verification_count(p_step_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM step_verifications WHERE step = (SELECT NULLIF(step_id, '') FROM steps WHERE step_id = p_step_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_steps_is_preparation_step
-- Field: Steps.IsPreparationStep
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_steps_is_preparation_step(p_step_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (((SELECT NULLIF(assigned_role, '') FROM steps WHERE step_id = p_step_id) = 'finance-analyst' OR (SELECT NULLIF(assigned_role, '') FROM steps WHERE step_id = p_step_id) = 'variance-review-agent'))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_steps_is_approval_step
-- Field: Steps.IsApprovalStep
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_steps_is_approval_step(p_step_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (((SELECT NULLIF(assigned_role, '') FROM steps WHERE step_id = p_step_id) = 'controller' OR (SELECT NULLIF(assigned_role, '') FROM steps WHERE step_id = p_step_id) = 'cfo'))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_steps_stale_authoritative_binding_count
-- Field: Steps.StaleAuthoritativeBindingCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_steps_stale_authoritative_binding_count(p_step_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM operational_bindings WHERE calc_operational_bindings_step_when_stale(operational_binding_id) = (SELECT NULLIF(step_id, '') FROM steps WHERE step_id = p_step_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_steps_inputs_are_fresh
-- Field: Steps.InputsAreFresh
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_steps_inputs_are_fresh(p_step_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_steps_stale_authoritative_binding_count(p_step_id))::NUMERIC = 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_steps_is_software_assigned
-- Field: Steps.IsSoftwareAssigned
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_steps_is_software_assigned(p_step_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_steps_assigned_agent_kind(p_step_id) AS val) SELECT (((SELECT val FROM __erb_dedup_v1) = 'AIAgent' OR (SELECT val FROM __erb_dedup_v1) = 'AutomatedPipeline'))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_steps_is_human_approval_gate
-- Field: Steps.IsHumanApprovalGate
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_steps_is_human_approval_gate(p_step_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((NOT (calc_steps_is_software_assigned(p_step_id)) AND ((SELECT NULLIF(step_id, '') FROM steps WHERE step_id = p_step_id) = 'policy-05' OR (SELECT NULLIF(step_id, '') FROM steps WHERE step_id = p_step_id) = 'close-06')))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_steps_gate_held_by_human
-- Field: Steps.GateHeldByHuman
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_steps_gate_held_by_human(p_step_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_steps_is_human_approval_gate(p_step_id) AND calc_steps_assigned_agent_kind(p_step_id) = 'Human'))::boolean;
$$ LANGUAGE sql STABLE;

