RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM operational_bindings WHERE calc_operational_bindings_step_when_unusable(operational_binding_id) = (SELECT NULLIF(step_id, '') FROM steps WHERE step_id = p_step_id)))::numeric;
