CREATE OR REPLACE FUNCTION calc_knowledge_fragments_is_compound_fragile(p_knowledge_fragment_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_knowledge_fragments_fragility_signal_count(p_knowledge_fragment_id))::NUMERIC >= 3)::boolean;
