-- calc_knowledge_fragments_reliance_surface_count
-- Field: KnowledgeFragments.RelianceSurfaceCount
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_knowledge_fragments_reliance_surface_count(p_knowledge_fragment_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_knowledge_fragments_is_invoked_by_an_exception(p_knowledge_fragment_id)) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_knowledge_fragments_ratified_boundary_count(p_knowledge_fragment_id)) AS v) __safe_numeric), 0)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_fragments_days_awaiting_my_approval
-- Field: KnowledgeFragments.DaysAwaitingMyApproval
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_knowledge_fragments_days_awaiting_my_approval(p_knowledge_fragment_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN calc_knowledge_fragments_is_my_unfinished_approval(p_knowledge_fragment_id) THEN ((calc_knowledge_fragments_as_of_instant(p_knowledge_fragment_id)::date - (SELECT valid_from::timestamptz FROM knowledge_fragments WHERE knowledge_fragment_id = p_knowledge_fragment_id)::date))::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_fragments_is_high_blast_radius_unapproved
-- Field: KnowledgeFragments.IsHighBlastRadiusUnapproved
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_fragments_is_high_blast_radius_unapproved(p_knowledge_fragment_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_knowledge_fragments_is_unapproved_and_operationally_live(p_knowledge_fragment_id) AND (calc_knowledge_fragments_reliance_surface_count(p_knowledge_fragment_id))::NUMERIC > 1));
$$ LANGUAGE sql STABLE;

-- calc_knowledge_fragments_is_long_unapproved
-- Field: KnowledgeFragments.IsLongUnapproved
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_fragments_is_long_unapproved(p_knowledge_fragment_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_knowledge_fragments_is_my_unfinished_approval(p_knowledge_fragment_id) AND (calc_knowledge_fragments_days_awaiting_my_approval(p_knowledge_fragment_id))::NUMERIC > 30));
$$ LANGUAGE sql STABLE;

-- calc_knowledge_fragments_unapproved_load_bearing_version_key
-- Field: KnowledgeFragments.UnapprovedLoadBearingVersionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_fragments_unapproved_load_bearing_version_key(p_knowledge_fragment_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_knowledge_fragments_is_high_blast_radius_unapproved(p_knowledge_fragment_id) THEN ((SELECT NULLIF(procedure_version, '') FROM knowledge_fragments WHERE knowledge_fragment_id = p_knowledge_fragment_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_fragments_is_orphaned_by_role
-- Field: KnowledgeFragments.IsOrphanedByRole
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_fragments_is_orphaned_by_role(p_knowledge_fragment_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_knowledge_fragments_is_currently_valid(p_knowledge_fragment_id) AND calc_knowledge_fragments_owner_role_is_vacated(p_knowledge_fragment_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_fragments_valid_fragment_version_key
-- Field: KnowledgeFragments.ValidFragmentVersionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_fragments_valid_fragment_version_key(p_knowledge_fragment_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_knowledge_fragments_is_currently_valid(p_knowledge_fragment_id) THEN ((SELECT NULLIF(procedure_version, '') FROM knowledge_fragments WHERE knowledge_fragment_id = p_knowledge_fragment_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_as_of_instant
-- Field: KnowledgeGaps.AsOfInstant
-- Type: lookup | DataType: datetime | Returns: TIMESTAMPTZ
-- Lookup: AsOfInstant from related EvaluationContexts


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_as_of_instant(p_knowledge_gap_id TEXT)
RETURNS TIMESTAMPTZ AS $$
  SELECT (SELECT as_of_instant::timestamptz FROM evaluation_contexts WHERE evaluation_context_id = (SELECT evaluation_context FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id));
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_owner_agent
-- Field: KnowledgeGaps.OwnerAgent
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: CurrentAgent from related Roles


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_owner_agent(p_knowledge_gap_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT current_agent::text FROM roles WHERE role_id = (SELECT owner_role FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id));
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_owner_is_still_engaged
-- Field: KnowledgeGaps.OwnerIsStillEngaged
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: IsStillEngaged from related Agents


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_owner_is_still_engaged(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT calc_agents_is_still_engaged(calc_knowledge_gaps_owner_agent(p_knowledge_gap_id));
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_owner_role_is_vacated
-- Field: KnowledgeGaps.OwnerRoleIsVacated
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: IsVacatedRole from related Roles


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_owner_role_is_vacated(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT calc_roles_is_vacated_role((SELECT owner_role FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id));
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_name
-- Field: KnowledgeGaps.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_name(p_knowledge_gap_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(severity, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id), ': ', LEFT(((SELECT NULLIF(statement, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id))::text, (60)::integer)))::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_open
-- Field: KnowledgeGaps.IsOpen
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_open(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (((SELECT NULLIF(status, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id) = 'Open' OR (SELECT NULLIF(status, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id) = 'Investigating'))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_open_gap_version_key
-- Field: KnowledgeGaps.OpenGapVersionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_open_gap_version_key(p_knowledge_gap_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN (calc_knowledge_gaps_is_open(p_knowledge_gap_id) AND (SELECT NULLIF(severity, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id) = 'High') THEN ((SELECT NULLIF(procedure_version, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_blocking
-- Field: KnowledgeGaps.IsBlocking
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_blocking(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(blocking_kind, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id) = 'Blocking')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_open_and_blocking
-- Field: KnowledgeGaps.IsOpenAndBlocking
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_open_and_blocking(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_knowledge_gaps_is_open(p_knowledge_gap_id) AND calc_knowledge_gaps_is_blocking(p_knowledge_gap_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_days_open
-- Field: KnowledgeGaps.DaysOpen
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_days_open(p_knowledge_gap_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN calc_knowledge_gaps_is_open(p_knowledge_gap_id) THEN ((calc_knowledge_gaps_as_of_instant(p_knowledge_gap_id)::date - (SELECT identified_at::timestamptz FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id)::date))::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_tolerance_days
-- Field: KnowledgeGaps.ToleranceDays
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_tolerance_days(p_knowledge_gap_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (SELECT NULLIF(severity, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id) = 'High' THEN (30)::text ELSE (CASE WHEN (SELECT NULLIF(severity, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id) = 'Medium' THEN (90)::text ELSE (180)::text END)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_overdue_gap
-- Field: KnowledgeGaps.IsOverdueGap
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_overdue_gap(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (calc_knowledge_gaps_days_open(p_knowledge_gap_id) > calc_knowledge_gaps_tolerance_days(p_knowledge_gap_id))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_has_resolution_plan
-- Field: KnowledgeGaps.HasResolutionPlan
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_has_resolution_plan(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(resolution_plan, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id) IS NOT NULL)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_abandoned_unknown
-- Field: KnowledgeGaps.IsAbandonedUnknown
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_abandoned_unknown(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_knowledge_gaps_is_overdue_gap(p_knowledge_gap_id) AND (NOT (calc_knowledge_gaps_has_resolution_plan(p_knowledge_gap_id)) OR NOT (calc_knowledge_gaps_owner_is_still_engaged(p_knowledge_gap_id)))))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_open_blocking_gap_version_key
-- Field: KnowledgeGaps.OpenBlockingGapVersionKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_open_blocking_gap_version_key(p_knowledge_gap_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_knowledge_gaps_is_open_and_blocking(p_knowledge_gap_id) THEN ((SELECT NULLIF(procedure_version, '') FROM knowledge_gaps WHERE knowledge_gap_id = p_knowledge_gap_id))::text ELSE ('')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_knowledge_gaps_is_ownerless_open_gap
-- Field: KnowledgeGaps.IsOwnerlessOpenGap
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_knowledge_gaps_is_ownerless_open_gap(p_knowledge_gap_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_knowledge_gaps_is_open(p_knowledge_gap_id) AND calc_knowledge_gaps_owner_role_is_vacated(p_knowledge_gap_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_faqs_name
-- Field: FAQs.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_faqs_name(p_faq_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(question, '') FROM faqs WHERE faq_id = p_faq_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_explanations_name
-- Field: Explanations.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_explanations_name(p_explanation_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(title, '') FROM explanations WHERE explanation_id = p_explanation_id))::text;
$$ LANGUAGE sql STABLE;

