CREATE OR REPLACE FUNCTION calc_procedure_executions_expected_step_count(p_procedure_execution_id TEXT)
RETURNS NUMERIC AS $$
  SELECT calc_procedure_versions_specified_step_count((SELECT procedure_version FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id));
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_executed_version_is_fit
-- Field: ProcedureExecutions.ExecutedVersionIsFit
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: IsFitToExecute from related ProcedureVersions


CREATE OR REPLACE FUNCTION calc_procedure_executions_executed_version_is_fit(p_procedure_execution_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT calc_procedure_versions_is_fit_to_execute((SELECT procedure_version FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id));
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_name
-- Field: ProcedureExecutions.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_procedure_executions_name(p_procedure_execution_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(procedure_version, '') FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id), ' / ', (SELECT NULLIF(context, '') FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_completed_step_count
-- Field: ProcedureExecutions.CompletedStepCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_procedure_executions_completed_step_count(p_procedure_execution_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM step_executions WHERE calc_step_executions_completed_execution_key(step_execution_id) = (SELECT NULLIF(procedure_execution_id, '') FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_control_breach_count
-- Field: ProcedureExecutions.ControlBreachCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_procedure_executions_control_breach_count(p_procedure_execution_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM step_executions WHERE calc_step_executions_control_breach_execution_key(step_execution_id) = (SELECT NULLIF(procedure_execution_id, '') FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_late_step_count
-- Field: ProcedureExecutions.LateStepCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_procedure_executions_late_step_count(p_procedure_execution_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM step_executions WHERE calc_step_executions_late_execution_key(step_execution_id) = (SELECT NULLIF(procedure_execution_id, '') FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_is_structurally_complete
-- Field: ProcedureExecutions.IsStructurallyComplete
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_procedure_executions_is_structurally_complete(p_procedure_execution_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (calc_procedure_executions_completed_step_count(p_procedure_execution_id) >= calc_procedure_executions_expected_step_count(p_procedure_execution_id))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_diverged_from_specification
-- Field: ProcedureExecutions.DivergedFromSpecification
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_procedure_executions_diverged_from_specification(p_procedure_execution_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((NOT (calc_procedure_executions_is_structurally_complete(p_procedure_execution_id)) OR (calc_procedure_executions_control_breach_count(p_procedure_execution_id))::NUMERIC > 0));
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_all_blocking_controls_evaluated
-- Field: ProcedureExecutions.AllBlockingControlsEvaluated
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_procedure_executions_all_blocking_controls_evaluated(p_procedure_execution_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_procedure_executions_unevaluated_blocking_total(p_procedure_execution_id))::NUMERIC = 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_unevaluated_blocking_total
-- Field: ProcedureExecutions.UnevaluatedBlockingTotal
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_procedure_executions_unevaluated_blocking_total(p_procedure_execution_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM step_executions WHERE calc_step_executions_unevaluated_blocking_execution_key(step_execution_id) = (SELECT NULLIF(procedure_execution_id, '') FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_separation_of_duties_held
-- Field: ProcedureExecutions.SeparationOfDutiesHeld
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_procedure_executions_separation_of_duties_held(p_procedure_execution_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_procedure_executions_separation_violation_count(p_procedure_execution_id))::NUMERIC = 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_separation_violation_count
-- Field: ProcedureExecutions.SeparationViolationCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_procedure_executions_separation_violation_count(p_procedure_execution_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM step_executions WHERE calc_step_executions_separation_violation_execution_key(step_execution_id) = (SELECT NULLIF(procedure_execution_id, '') FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_is_attestation_ready
-- Field: ProcedureExecutions.IsAttestationReady
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_procedure_executions_is_attestation_ready(p_procedure_execution_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_procedure_executions_is_structurally_complete(p_procedure_execution_id) AND NOT (calc_procedure_executions_diverged_from_specification(p_procedure_execution_id)) AND calc_procedure_executions_all_blocking_controls_evaluated(p_procedure_execution_id) AND calc_procedure_executions_separation_of_duties_held(p_procedure_execution_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_attestation_blocker_summary
-- Field: ProcedureExecutions.AttestationBlockerSummary
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_procedure_executions_attestation_blocker_summary(p_procedure_execution_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_procedure_executions_is_attestation_ready(p_procedure_execution_id) THEN ('')::text ELSE (CASE WHEN NOT (calc_procedure_executions_is_structurally_complete(p_procedure_execution_id)) THEN ('Incomplete: specified steps did not all complete.')::text ELSE (CASE WHEN (calc_procedure_executions_separation_violation_count(p_procedure_execution_id))::NUMERIC > 0 THEN ('Segregation of duties violated.')::text ELSE (CASE WHEN (calc_procedure_executions_unevaluated_blocking_total(p_procedure_execution_id))::NUMERIC > 0 THEN ('Blocking controls were never evaluated.')::text ELSE ('Control breach recorded on one or more steps.')::text END)::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_signed_against_unfit_version
-- Field: ProcedureExecutions.SignedAgainstUnfitVersion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_procedure_executions_signed_against_unfit_version(p_procedure_execution_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (((SELECT NULLIF(execution_status, '') FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id) = 'Completed' AND NOT (calc_procedure_executions_executed_version_is_fit(p_procedure_execution_id))))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_asserted_only_control_count
-- Field: ProcedureExecutions.AssertedOnlyControlCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_procedure_executions_asserted_only_control_count(p_procedure_execution_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM requirement_satisfactions WHERE calc_requirement_satisfactions_asserted_only_execution_key(requirement_satisfaction_id) = (SELECT NULLIF(procedure_execution_id, '') FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_assurance_is_mostly_asserted
-- Field: ProcedureExecutions.AssuranceIsMostlyAsserted
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_procedure_executions_assurance_is_mostly_asserted(p_procedure_execution_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_procedure_executions_asserted_only_control_count(p_procedure_execution_id))::NUMERIC > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_unreachable_handling_failure_count
-- Field: ProcedureExecutions.UnreachableHandlingFailureCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_procedure_executions_unreachable_handling_failure_count(p_procedure_execution_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM message_deliveries WHERE calc_message_deliveries_unreachable_failure_key(message_delivery_id) = (SELECT NULLIF(procedure_execution_id, '') FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_retention_breach_count
-- Field: ProcedureExecutions.RetentionBreachCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_procedure_executions_retention_breach_count(p_procedure_execution_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM message_deliveries WHERE calc_message_deliveries_retention_breach_execution_key(message_delivery_id) = (SELECT NULLIF(procedure_execution_id, '') FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_cleared_legal_review_count
-- Field: ProcedureExecutions.ClearedLegalReviewCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_procedure_executions_cleared_legal_review_count(p_procedure_execution_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM step_executions WHERE calc_step_executions_cleared_legal_review_key(step_execution_id) = (SELECT NULLIF(procedure_execution_id, '') FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_has_cleared_legal_review
-- Field: ProcedureExecutions.HasClearedLegalReview
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_procedure_executions_has_cleared_legal_review(p_procedure_execution_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_procedure_executions_cleared_legal_review_count(p_procedure_execution_id))::NUMERIC > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_abandoned_failure_count
-- Field: ProcedureExecutions.AbandonedFailureCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_procedure_executions_abandoned_failure_count(p_procedure_execution_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM message_deliveries WHERE calc_message_deliveries_abandoned_failure_execution_key(message_delivery_id) = (SELECT NULLIF(procedure_execution_id, '') FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_delivered_count
-- Field: ProcedureExecutions.DeliveredCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_procedure_executions_delivered_count(p_procedure_execution_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM message_deliveries WHERE calc_message_deliveries_reached_execution_key(message_delivery_id) = (SELECT NULLIF(procedure_execution_id, '') FROM procedure_executions WHERE procedure_execution_id = p_procedure_execution_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_procedure_executions_total_delivery_attempt_count
