CREATE OR REPLACE FUNCTION calc_step_executions_has_unevaluated_blocking_control(p_step_execution_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_step_executions_unevaluated_blocking_count(p_step_execution_id))::NUMERIC > 0)::boolean;
$$ LANGUAGE sql STABLE;

