CREATE OR REPLACE FUNCTION calc_test_cases_is_passing(p_test_case_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(last_outcome, '') FROM test_cases WHERE test_case_id = p_test_case_id) = 'PASS')::boolean;
