RETURNS TEXT AS $$
  SELECT (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT message_template FROM template_approvals WHERE template_approval_id = p_template_approval_id));
$$ LANGUAGE sql STABLE;

